-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.release_digests_fingerprint(pub jsonb, drf jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select md5(coalesce(string_agg(x.s || x.key || ':' || x.value::text, ';' order by x.s, x.key), ''))
    from (select 'draft.' as s, e.key, e.value from jsonb_each(drf) e where drf is not null
          union all
          select case when drf is null then '' else 'public.' end, e.key, e.value from jsonb_each(pub) e) x;
$function$;
